		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_condition] stg
		LEFT JOIN [synapse_ce].[apuk_condition] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
